'use client'

import { useFormStatus } from 'react-dom'

export default function SyncButton() {
  const { pending } = useFormStatus()
  return (
    <button type="submit" disabled={pending}>
      {pending ? 'Starting sync…' : 'Sync latest catalog'}
    </button>
  )
}

import { unstable_cache } from 'next/cache'
import { getAllProducts } from './db'

export type Product = {
  id: number
  name: string
  price: number
  stock: number
  available: boolean
}

// The catalog is read-heavy, so serve it from the Data Cache instead of
// re-querying on every request. Tagged "products" so a single
// revalidateTag("products") refreshes every view that reads this catalog.
export const getCachedProducts: () => Promise<Product[]> = unstable_cache(
  async () => getAllProducts(),
  ['catalog', 'all-products'],
  { tags: ['products'] },
)

// In-memory catalog source. In production this would be your database / an
// ERP-PIM mirror. Kept in-memory here so the background sync is observable
// across reads. The shape of each entry mirrors what an ERP/PIM push would
// update: pricing, inventory and availability.
let catalog = [
  { id: 1, name: 'Laptop', price: 999, stock: 12, available: true },
  { id: 2, name: 'Phone', price: 699, stock: 0, available: false },
  { id: 3, name: 'Tablet', price: 499, stock: 31, available: true },
  { id: 4, name: 'Headphones', price: 199, stock: 8, available: true },
  { id: 5, name: 'Watch', price: 299, stock: 22, available: true },
]

let syncRuns = 0

export async function getAllProducts() {
  // Simulate database delay.
  await new Promise((resolve) => setTimeout(resolve, 100))
  return catalog
}

// Pull the latest pricing / inventory / availability from the upstream ERP/PIM.
// In practice this touches thousands of SKUs, so it is intentionally slow —
// which is exactly why admins must not be made to wait on it.
export async function syncProductsFromUpstream() {
  await new Promise((resolve) => setTimeout(resolve, 3000))

  syncRuns += 1
  catalog = catalog.map((product) => ({
    ...product,
    stock: Math.max(0, product.stock + Math.floor(Math.random() * 20) - 8),
    price: Math.round(product.price * (1 + (Math.random() * 0.1 - 0.05))),
    available: true,
  }))

  return { syncedAt: new Date().toISOString(), skus: catalog.length, runs: syncRuns }
}

import { after } from 'next/server'
import { revalidateTag } from 'next/cache'
import { getCachedProducts } from '@/lib/catalog'
import { syncProductsFromUpstream } from '@/lib/db'
import SyncButton from './sync-button'

// Admin dashboards should reflect catalog mutations, so render per request.
// The expensive read is still served from the "products" Data Cache, so this
// stays fast — only the cache rebuild re-queries, and only after a sync.
export const dynamic = 'force-dynamic'

export const metadata = { title: 'Admin · Product Catalog' }

// Inline Server Action: schedules the heavy sync to run AFTER the response is
// flushed to the admin, then invalidates the "products" cache. The action
// itself returns immediately, so the page stays responsive and the catalog is
// only briefly stale until the background sync lands.
async function syncCatalog() {
  'use server'

  after(async () => {
    await syncProductsFromUpstream()
    revalidateTag('products')
  })
}

const money = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
})

export default async function CatalogPage() {
  const products = await getCachedProducts()

  return (
    <main
      style={{
        fontFamily: 'system-ui, sans-serif',
        maxWidth: 960,
        margin: '0 auto',
        padding: 24,
      }}
    >
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          gap: 16,
        }}
      >
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '4px 0 0', color: '#666' }}>
            Cached for fast browsing. Sync pulls the latest pricing, inventory
            &amp; availability from the ERP/PIM.
          </p>
        </div>
        <form action={syncCatalog}>
          <SyncButton />
        </form>
      </header>

      <p style={{ color: '#666', fontSize: 14 }}>
        Sync runs in the background — keep working. The list updates here and
        across every catalog view shortly after.
      </p>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 16 }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '2px solid #eee' }}>
            <th style={{ padding: 8 }}>ID</th>
            <th style={{ padding: 8 }}>Name</th>
            <th style={{ padding: 8 }}>Price</th>
            <th style={{ padding: 8 }}>Stock</th>
            <th style={{ padding: 8 }}>Available</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: 8 }}>{product.id}</td>
              <td style={{ padding: 8 }}>{product.name}</td>
              <td style={{ padding: 8 }}>{money.format(product.price)}</td>
              <td style={{ padding: 8 }}>{product.stock}</td>
              <td style={{ padding: 8 }}>{product.available ? 'Yes' : 'No'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

import { redirect } from 'next/navigation'

export default function Page() {
  redirect('/catalog')
}

