export async function syncProductsFromUpstream() {
  console.error('[sync] start')
  await new Promise((resolve) => setTimeout(resolve, 3000))

  syncRuns += 1
  catalog = catalog.map((product) => ({
    ...product,
    stock: Math.max(0, product.stock + Math.floor(Math.random() * 20) - 8),
    price: Math.round(product.price * (1 + (Math.random() * 0.1 - 0.05))),
    available: true,
  }))

  console.error('[sync] done prices=', catalog.map((p) => p.price).join(','))
  return { syncedAt: new Date().toISOString(), skus: catalog.length, runs: syncRuns }
}

