// ERP-PIM mirror. Kept in-memory here so the background sync is observable
// across reads. The shape of each entry mirrors what an ERP/PIM push would
// update: pricing, inventory and availability.
let catalog = [
  { id: 1, name: 'Laptop', price: 999, stock: 12, available: true },
  { id: 2, name: 'Phone', price: 699, stock: 0, available: false },
  { id: 3, name: 'Tablet', price: 499, stock: 31, available: true },
